/** Grammar lowering only: ellipsis lists become bounded RangeNodes in the
 * mathematical AST. Values are generated by the evaluator, never by text expansion. */
export function parseListRanges(source: string): string {
  const read = (text: string): string => {
    let output = "";
    for (let i = 0; i < text.length; i++) {
      if (text[i] !== "[") {
        output += text[i];
        continue;
      }
      let depth = 1,
        end = i + 1;
      for (; end < text.length && depth; end++) {
        if (text[end] === "[") depth++;
        if (text[end] === "]") depth--;
      }
      if (depth) throw new Error("Complete the list brackets.");
      const body = text.slice(i + 1, end - 1);
      const parts = body.split(/\.\.\.|…/);
      if (parts.length === 1) output += `[${read(body)}]`;
      else {
        if (parts.length !== 2) throw new Error("Use one ellipsis per range.");
        const prefix = parts[0].replace(/,\s*$/, "");
        const seeds: string[] = [];
        let level = 0,
          start = 0;
        for (let j = 0; j < prefix.length; j++) {
          if ("([".includes(prefix[j])) level++;
          if (")]".includes(prefix[j])) level--;
          if (prefix[j] === "," && level === 0) {
            seeds.push(prefix.slice(start, j));
            start = j + 1;
          }
        }
        seeds.push(prefix.slice(start));
        const last = parts[1].replace(/^\s*,/, "").trim();
        if (seeds.length > 2 || seeds.some((s) => !s.trim()) || !last)
          throw new Error("Use [start...end] or [first,second...end].");
        const first = read(seeds[0]);
        const step =
          seeds.length === 2 ? `((${read(seeds[1])})-(${first}))` : undefined;
        output += `((${first}):${step ? step + ":" : ""}(${read(last)}))`;
      }
      i = end - 1;
    }
    return output;
  };
  return read(source);
}

export function rangeValues(
  start: number,
  step: number,
  end: number,
): number[] {
  if (![start, step, end].every(Number.isFinite) || step === 0)
    throw new Error("List ranges need finite endpoints and a nonzero step.");
  const intervals = (end - start) / step;
  if (intervals < 0)
    throw new Error("Range step must move toward the endpoint.");
  const count = Math.round(intervals) + 1;
  if (count > 200 || !Number.isSafeInteger(count))
    throw new Error("Lists support at most 200 values Offline.");
  const values = Array.from({ length: count }, (_, i) => start + i * step);
  if (values.some((value) => !Number.isFinite(value)))
    throw new Error("This list exceeds the supported numeric range.");
  return values;
}
